mapper.select:
SELECT concat('HT-', h.id) AS id, concat('FI-', h.instance_id) AS instId, concat('def_', h.definition_id) AS defId, d.flow_name AS defName, h.node_name AS node, coalesce(u.actual_name, h.approver) AS handler, case when h.cooperate_type = 2 then '转办' when h.cooperate_type = 3 then '委派' when h.cooperate_type = 6 then '加签' when h.skip_type = 'REJECT' then '驳回' when h.skip_type = 'PASS' then '同意' else '提交' end AS result, coalesce(h.message, '') AS opinion, date_format(h.update_time, '%Y-%m-%d %H:%i') AS time, timestampdiff(minute, h.create_time, h.update_time) AS cost, h.node_code, h.target_node_code FROM flow_his_task h LEFT JOIN flow_definition d ON h.definition_id = d.id LEFT JOIN sys_user u ON u.employee_id = cast(h.approver as unsigned)
h.del_flag = '0'
AND case when h.cooperate_type = 2 then '转办' when h.cooperate_type = 6 then '加签' when h.skip_type = 'REJECT' then '驳回' when h.skip_type = 'PASS' then '同意' else '提交' end = #{p.result}
AND h.instance_id = #{p.instanceId}
ORDER BY h.update_time DESC
